{"task": "Publish and read a generation/checksum pair consistently. Every checksum must equal generation XOR 0x5a5a, and the final generation must remain 12000. Retain every scheduling hook.", "editable_files": ["solution.c"], "sources": {"solution.c": "#include "state.h"
#include <sched.h>
void publish_stamp(Stamp *stamp,int generation) {
    pthread_mutex_lock(&stamp->mutex);
    stamp->generation=generation;
    pthread_mutex_unlock(&stamp->mutex);
    sched_yield();
    pthread_mutex_lock(&stamp->mutex);
    stamp->checksum=generation ^ 0x5a5a;
    pthread_mutex_unlock(&stamp->mutex);
}
void read_stamp(Stamp *stamp,int *generation,int *checksum) {
    *generation=stamp->generation;
    sched_yield();
    *checksum=stamp->checksum;
}
"}, "headers": {"state.h": "#ifndef STATE_H
#define STATE_H
#include <pthread.h>
typedef struct { pthread_mutex_t mutex; int generation; int checksum; } Stamp;
void publish_stamp(Stamp *,int);
void read_stamp(Stamp *,int *,int *);
#endif
"}, "requirements": ["Publish and read a generation/checksum pair consistently. Every checksum must equal generation XOR 0x5a5a, and the final generation must remain 12000. Retain every scheduling hook."]}
